using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tool instances ---
var notepad = new Notepad();

// --- Build the agent ---
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearch.SearchAsync),
    AIFunctionFactory.Create(notepad.SaveNote),
    AIFunctionFactory.Create(notepad.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic you:
        1. Search the web multiple times with different queries to gather information.
        2. Save important findings as notes using the note-taking tool.
        3. After gathering enough information, retrieve all notes and produce a
           well-structured summary with key points and sources.
        Always search at least 3 times with varied queries before summarizing.
        """,
    name: "ResearchAgent",
    description: "Researches a topic by searching the web and summarizing findings.",
    tools: tools,
    loggerFactory: null,
    services: null);

// --- Run the agent ---
Console.WriteLine("Research Agent");
Console.WriteLine(new string('─', 40));
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync(
    conversationId: Guid.NewGuid().ToString());

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions);

Console.WriteLine(new string('─', 40));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('─', 40));
Console.WriteLine(response.Text);
