+/// <summary>Simulated web search tool.</summary>
+static class WebSearch
+{
+    private static readonly HttpClient Http = new()
+    {
+        Timeout = TimeSpan.FromSeconds(15),
+    };
+
+    [Description("Searches the web for the given query and returns a list of result snippets.")]
+    public static async Task<string> SearchAsync(
+        [Description("The search query string")] string query)
+    {
+        Console.WriteLine($"  🔍 Searching: \"{query}\"");
+
+        // Use DuckDuckGo instant-answer API (no key required).
+        var encoded = Uri.EscapeDataString(query);
+        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
+
+        try
+        {
+            var json = await Http.GetStringAsync(url);
+            using var doc = System.Text.Json.JsonDocument.Parse(json);
+            var root = doc.RootElement;
+
+            var results = new List<string>();
+
+            // Abstract text
+            var abstractText = root.GetProperty("AbstractText").GetString();
+            var abstractSource = root.GetProperty("AbstractSource").GetString();
+            if (!string.IsNullOrWhiteSpace(abstractText))
+                results.Add($"[{abstractSource}] {abstractText}");
+
+            // Related topics
+            if (root.TryGetProperty("RelatedTopics", out var topics))
+            {
+                foreach (var t in topics.EnumerateArray().Take(5))
+                {
+                    var text = t.TryGetProperty("Text", out var txt)
+                        ? txt.GetString() : null;
+                    if (!string.IsNullOrWhiteSpace(text))
+                        results.Add(text);
+                }
+            }
+
+            if (results.Count == 0)
+                return $"No detailed results found for \"{query}\". Try a different query.";
+
+            return string.Join("\n\n", results);
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed ({ex.Message}). Try a different query.";
+        }
+    }
+}
+
+/// <summary>Note-taking tool that stores research findings.</summary>
+class Notepad
+{
+    private readonly List<string> _notes = [];
+
+    public int Count => _notes.Count;
+
+    [Description("Saves a research note. Use this to record important findings from search results.")]
+    public string SaveNote(
+        [Description("The note content to save")] string note)
+    {
+        _notes.Add(note);
+        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
+        return $"Note saved. You now have {_notes.Count} note(s).";
+    }
+
+    [Description("Retrieves all saved research notes.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        var sb = new System.Text.StringBuilder();
+        for (var i = 0; i < _notes.Count; i++)
+            sb.AppendLine($"Note {i + 1}: {_notes[i]}");
+        return sb.ToString();
+    }
+}
